#Requires -Version 7.0
<#
.SYNOPSIS
    Read-only R21 remediation-delta checks for PLAN-FRENEMY-002.
.DESCRIPTION
    Recomputes source-binding blobs, delta paths, ZIP entry equality, manifest
    differences, and evidence hashes. Writes nothing except the JSON result file.
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$WorkspacePath,
    [Parameter(Mandatory)][string]$OutputPath
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$base = '49365a078fe2c3554cbdba5dc799e099a9715db5'
$head = '82e90f9df5047634767a3395a72ba76150e80d44'
$testHead = '20fe8cc011de553a08d53d5ed4630eabad742280'
$r21 = 'docs/receipts/hv/20261109T170519-four-agent-reasoning-claude-hv-r21'

Push-Location -LiteralPath $WorkspacePath
try {
    $result = [ordered]@{ checkedAtLocal = (Get-Date -Format s) }

    # Source binding: recompute every blob at the test head and in the working tree.
    $sb = Get-Content -Raw -LiteralPath "$r21/source-binding.json" | ConvertFrom-Json
    $bindings = foreach ($b in $sb.testedSourceBindings) {
        $atTest = (git rev-parse "${testHead}:$($b.relativePath)").Trim()
        $wt = (git hash-object -- $b.relativePath).Trim()
        $atHead = (git rev-parse "${head}:$($b.relativePath)").Trim()
        [ordered]@{
            path = $b.relativePath
            testHeadBlob = $atTest
            headBlob = $atHead
            workingTreeBlob = $wt
            sha256 = (Get-FileHash -LiteralPath $b.relativePath -Algorithm SHA256).Hash
            receiptTestBlobMatches = ($atTest -eq $b.testHeadGitBlob)
            receiptWorkingBlobMatches = ($wt -eq $b.currentWorkingTreeGitBlob)
            receiptShaMatches = ((Get-FileHash -LiteralPath $b.relativePath -Algorithm SHA256).Hash -eq $b.currentWorkingTreeSha256)
            unchanged = ($atTest -eq $wt -and $atTest -eq $atHead)
        }
    }
    $result.sourceBindingCount = @($bindings).Count
    $result.sourceBindingAllUnchanged = (@($bindings | Where-Object { -not $_.unchanged }).Count -eq 0)
    $result.sourceBindingAllReceiptFieldsMatch = (@($bindings | Where-Object { -not ($_.receiptTestBlobMatches -and $_.receiptWorkingBlobMatches -and $_.receiptShaMatches) }).Count -eq 0)
    $result.sourceBindings = @($bindings)

    # Delta paths.
    $result.testHeadToHeadPaths = @(git diff --name-only $testHead $head)
    $result.testHeadToHeadNonDocPaths = @($result.testHeadToHeadPaths | Where-Object { $_ -notlike 'docs/*' })
    $result.remediationDeltaPaths = @(git diff --name-only $base $head)
    $result.deltaCommits = @(git log --format=%H "$base..$head")

    # ZIP entries against on-disk wiki files.
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    $zip = [IO.Compression.ZipFile]::OpenRead((Join-Path $WorkspacePath 'docs/requirements/requirements-wiki-documents.zip'))
    try {
        $entries = foreach ($e in $zip.Entries) {
            if ($e.FullName.EndsWith('/')) { continue }
            $candidates = @("docs/Project/wiki/$($e.FullName)", "docs/Project/$($e.FullName)", $e.FullName)
            $disk = $candidates | Where-Object { Test-Path -LiteralPath $_ -PathType Leaf } | Select-Object -First 1
            $stream = $e.Open()
            $ms = [IO.MemoryStream]::new()
            try { $stream.CopyTo($ms) } finally { $stream.Dispose() }
            $zipHash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($ms.ToArray()))
            $diskHash = if ($disk) { (Get-FileHash -LiteralPath $disk -Algorithm SHA256).Hash } else { $null }
            [ordered]@{ entry = $e.FullName; disk = $disk; matches = ($null -ne $diskHash -and $zipHash -eq $diskHash) }
        }
    }
    finally { $zip.Dispose() }
    $result.zipEntryCount = @($entries).Count
    $result.zipMismatchCount = @($entries | Where-Object { -not $_.matches }).Count
    $result.zipMismatches = @($entries | Where-Object { -not $_.matches })
    $result.zipPlanEntries = @($entries | Where-Object { $_.entry -match 'Four-Agent|Validation-Status' })

    # Manifests: only generatedAtUtc may differ from the accepted base.
    $result.manifests = foreach ($m in 'docs/Project/wiki/azure/.mcp-requirements-manifest.json', 'docs/Project/wiki/github/.mcp-requirements-manifest.json') {
        $old = (git show "${base}:$m") -join "`n" | ConvertFrom-Json -AsHashtable
        $new = Get-Content -Raw -LiteralPath $m | ConvertFrom-Json -AsHashtable
        $oldGen = $old['generatedAtUtc']; $newGen = $new['generatedAtUtc']
        $old.Remove('generatedAtUtc'); $new.Remove('generatedAtUtc')
        [ordered]@{
            path = $m
            baseGeneratedAtUtc = "$oldGen"
            headGeneratedAtUtc = "$newGen"
            restIdentical = (($old | ConvertTo-Json -Depth 50 -Compress) -eq ($new | ConvertTo-Json -Depth 50 -Compress))
            diffLines = @(git diff --unified=0 $base $head -- $m | Where-Object { $_ -match '^[+-][^+-]' })
        }
    }

    # Evidence hashes named in the request.
    $req = Get-Content -Raw -LiteralPath "$r21/request.jsonl" | ConvertFrom-Json
    $result.hashes = [ordered]@{
        prompt = [ordered]@{ expected = $req.promptSha256; actual = (Get-FileHash -LiteralPath "$r21/review-prompt.md").Hash }
        sourceBinding = [ordered]@{ expected = $req.sourceReceipt.sha256; actual = (Get-FileHash -LiteralPath "$r21/source-binding.json").Hash }
        chat = [ordered]@{ expected = $req.parentChat.chatSha256; actual = (Get-FileHash -LiteralPath "$r21/parent-chat-unredacted-r20-to-r21.jsonl").Hash }
        chatPublic = [ordered]@{ actual = (Get-FileHash -LiteralPath "$r21/parent-chat-unredacted-r20-to-r21.public-credential-safe.jsonl").Hash }
        manifest = [ordered]@{ expected = $req.parentChat.manifestSha256; actual = (Get-FileHash -LiteralPath "$r21/parent-chat-unredacted-r20-to-r21.manifest.json").Hash }
        r19Verdict = [ordered]@{ expected = $req.priorReview.verdictSha256; actual = (Get-FileHash -LiteralPath $req.priorReview.verdictPath).Hash }
        r19Request = [ordered]@{ expected = 'C9F3B7AC5BFEF4D3730410D6F873136F9FEE8178C415D5EC3861B3477A88873C'; actual = (Get-FileHash -LiteralPath 'docs/receipts/hv/20261109T151227-four-agent-reasoning-claude-hv-r19/request.jsonl').Hash }
        r19Response = [ordered]@{ expected = '0EC4B468A5C9DABA1BFE5F51146235E33A88B957AC302DE5C962AAA23A0D761A'; actual = (Get-FileHash -LiteralPath 'docs/receipts/hv/20261109T151227-four-agent-reasoning-claude-hv-r19/response.jsonl').Hash }
        r20DocValidation = [ordered]@{ expected = '735BED0F2FED8BD0693411AA4F5E99C2809C11B7E2C5DDDAF97CE8DEB8420685'; actual = (Get-FileHash -LiteralPath 'docs/receipts/hv/20261109T151227-four-agent-reasoning-claude-hv-r19/r20-documentation-validation.json').Hash }
    }
    foreach ($k in @($result.hashes.Keys)) {
        $h = $result.hashes[$k]
        if ($h.Contains('expected')) { $h.matches = ($h.expected -eq $h.actual) }
    }
    $result.missingEvidencePaths = @($req.evidencePaths | Where-Object { -not (Test-Path -LiteralPath $_) })

    # Prohibited dashes in the delta-touched authored files.
    $dash = [string][char]0x2014; $en = [string][char]0x2013
    $result.dashHits = @('docs/plans/four-agent-reasoning-integration.md', 'docs/testing/validation.md',
        'docs/receipts/hv/20261109T140625-four-agent-reasoning-claude-hv-r18/correction-20261109T145809.md',
        'docs/receipts/hv/20261109T151227-four-agent-reasoning-claude-hv-r19/correction-20261109T155052.md') |
        ForEach-Object { $t = Get-Content -Raw -LiteralPath $_; [ordered]@{ path = $_; em = ([regex]::Matches($t, $dash)).Count; en = ([regex]::Matches($t, $en)).Count } }

    $result | ConvertTo-Json -Depth 20 | Out-File -LiteralPath $OutputPath -Encoding utf8
}
finally { Pop-Location }

